import type { MotionProps } from "motion/react";
import { MotionConfig, motion } from "motion/react";
import type { ElementType, JSX } from "react";

import { cn } from "#/utils/cn";

type MotionHTMLProps = MotionProps & Record<string, unknown>;

// Cache motion components at module level to avoid creating during render
const motionComponentCache = new Map<
	keyof JSX.IntrinsicElements,
	React.ComponentType<MotionHTMLProps>
>();

const getMotionComponent = (element: keyof JSX.IntrinsicElements) => {
	let component = motionComponentCache.get(element);
	if (!component) {
		component = motion.create(element);
		motionComponentCache.set(element, component);
	}
	return component;
};

interface TextShimmerProps {
	children: string;
	as?: ElementType;
	className?: string;
	duration?: number;
	spread?: number;
}

const ShimmerComponent = ({
	children,
	as: Component = "p",
	className,
	duration = 2,
	spread = 2,
}: TextShimmerProps) => {
	const MotionComponent = getMotionComponent(
		Component as keyof JSX.IntrinsicElements,
	);

	const dynamicSpread = (children?.length ?? 0) * spread;

	return (
		<MotionConfig reducedMotion="user">
			<MotionComponent
				data-pixel="ignore"
				animate={{ backgroundPosition: "0% center" }}
				className={cn(
					"relative inline-block bg-[length:250%_100%,auto] bg-clip-text text-transparent",
					"[--bg:linear-gradient(90deg,#0000_calc(50%-var(--spread)),hsl(var(--surface-primary)),#0000_calc(50%+var(--spread)))] [background-repeat:no-repeat,padding-box]",
					className,
				)}
				initial={{ backgroundPosition: "100% center" }}
				style={{
					"--spread": `${dynamicSpread}px`,
					backgroundImage:
						"var(--bg), linear-gradient(hsl(var(--content-secondary)), hsl(var(--content-secondary)))",
				}}
				transition={{
					duration,
					ease: "linear",
					repeat: Number.POSITIVE_INFINITY,
				}}
			>
				{children}
			</MotionComponent>
		</MotionConfig>
	);
};

export const Shimmer = ShimmerComponent;
